package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathMissingException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl.cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_AtMean() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // For a normal distribution, P(X <= mean) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(mean), DELTA);
    }

    @Test
    public void testCumulativeProbability_PositiveZScore() {
        double mean = 10.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // x = 12 is 1 SD above mean. P(Z <= 1) is approx 0.841344746
        double result = dist.cumulativeProbability(12.0);
        Assert.assertTrue(result > 0.5 && result < 1.0);
        Assert.assertEquals(0.8413447460685429, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_NegativeZScore() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // x = -1 is 1 SD below mean. P(Z <= -1) is approx 0.158655253
        double result = dist.cumulativeProbability(-1.0);
        Assert.assertTrue(result < 0.5 && result > 0.0);
        Assert.assertEquals(0.15865525393145707, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_ExtremeUpperBoundary() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // dev = 41.0. 41 > 40 * 1.0. Should trigger the if branch returning 1.0d
        double result = dist.cumulativeProbability(41.0);
        Assert.assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testCumulativeProbability_ExtremeLowerBoundary() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // dev = -41.0. abs(-41) > 40 * 1.0. Should trigger the if branch returning 1.0d? 
        // Wait, looking at the code: return false ? 0.0d : 1.0d; 
        // 'false' is a constant, so it always returns 1.0d according to the provided snippet.
        double result = dist.cumulativeProbability(-41.0);
        Assert.assertEquals(1.0, result, 0.0);
    }

    @Test
    public void testCumulativeProbability_BoundaryCaseNearThreshold() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // dev = 39.9. 39.9 is not > 40. Should go to Erf calculation.
        double result = dist.cumulativeProbability(39.9);
        Assert.assertTrue(result <= 1.0 && result >= 0.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidSD() {
        // Assuming constructor validates SD > 0
        new NormalDistributionImpl(0.0, -1.0);
    }

    @Test
    public void testCumulativeProbability_ConsistencyWithInverse() {
        double mean = 5.0;
        double sd = 2.5;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        double x = 7.0;
        double p = dist.cumulativeProbability(x);
        // inverseCumulativeProbability(p) should return x
        Assert.assertEquals(x, dist.inverseCumulativeProbability(p), 1e-8);
    }
}
